// Single writer to `tasks`. Builds a parameterised statement per action.
// No string concatenation of user input into SQL: values ride in params.
const i = $input.first().json;
const action = i.action || 'create';
const M = {
  create:   { sql: `INSERT INTO tasks (user_id, agent_id, thread, title, detail, state, origin, source_message_id, due_at)
                    VALUES ($1::uuid,(SELECT id FROM agents WHERE slug=$2),$3,$4,$5,'todo',$6,$7::uuid,$8)
                    RETURNING id::text`,
              params: [i.user_id, i.agent, i.thread || null, i.title, i.detail || null,
                       i.origin || 'user', i.source_message_id || null, i.due_at || null] },
  start:    { sql: `UPDATE tasks SET state='in_progress', started_at=NOW() WHERE id=$1::uuid RETURNING id::text`,
              params: [i.task_id] },
  block:    { sql: `UPDATE tasks SET state='blocked', blocked_reason=$2, resume_url=$3,
                    blocked_until=NOW()+INTERVAL '48 hours' WHERE id=$1::uuid RETURNING id::text`,
              params: [i.task_id, i.reason || null, i.resume_url || null] },
  complete: { sql: `UPDATE tasks SET state='done', completed_at=NOW() WHERE id=$1::uuid RETURNING id::text`,
              params: [i.task_id] },
  cancel:   { sql: `UPDATE tasks SET state='cancelled', cancelled_at=NOW() WHERE id=$1::uuid RETURNING id::text`,
              params: [i.task_id] },
};
const m = M[action];
if (!m) throw new Error(`svc.board: unknown action '${action}'`);
if (action === 'create' && !i.title) throw new Error('svc.board: create needs a title');
if (action !== 'create' && !i.task_id) throw new Error(`svc.board: ${action} needs a task_id`);
return [{ json: { ...i, action, sql: m.sql, params: m.params } }];

