SELECT t.id::text AS task_id, t.title, t.detail, t.state, t.due_at,
       t.calendar_event_id, a.name AS agent_name, a.calendar_color_id
FROM tasks t JOIN agents a ON a.id=t.agent_id WHERE t.id=$1::uuid;
